    const nick = el('input', { type: 'text', maxlength: '30', value: f.nick });
    const emoji = el('input', { type: 'text', maxlength: '4', value: f.emoji });
    const color = el('input', { type: 'color', value: u.safeColor(f.color) });
    const bio = el('textarea', { rows: '2', maxlength: '160', text: f.bio });
    const quote = el('input', { type: 'text', maxlength: '100', value: f.quote });
    const last = el('input', { type: 'text', maxlength: '80', value: f.lastSeen });
    const threat = el('input', { type: 'number', min: '0', max: '100', value: String(f.threat) });
    const crimes = el('textarea', { rows: '3', text: (f.crimes || []).join('\n') });
    const rates = {};
    const rateWrap = el('div', { class: 'grid-rates' });
    st.traits.forEach(function (t) {
      rates[t.key] = el('input', { type: 'number', min: '0', max: '100', value: String(f.ratings[t.key] === undefined ? 50 : f.ratings[t.key]) });
      rateWrap.append(fld(t.icon + ' ' + t.label + ' (0-100)', rates[t.key]));
    });
    let photo = f.photo || '';
